absl::Status Parser::action34([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTNode*>();
{
      if (std::get<std::vector<ASTPipeOperator*>>(rhs[1].value).empty()) {
        std::get<ASTNode*>(lhs.value) = std::get<ASTNode*>(rhs[0].value);
      } else if(language_options.LanguageFeatureEnabled(
                    FEATURE_STATEMENT_WITH_PIPE_OPERATORS)) {
        auto pipe_suffix =
            MakeNode<ASTSubpipelineStatement>(rhs[1].sym.location,
                MakeNode<ASTSubpipeline>(rhs[1].sym.location, std::get<std::vector<ASTPipeOperator*>>(rhs[1].value)));
        std::get<ASTNode*>(lhs.value) = MakeNode<ASTStatementWithPipeOperators>(lhs.sym.location, std::get<ASTNode*>(rhs[0].value), pipe_suffix);
      } else {
        return MakeSyntaxError(rhs[1].sym.location,
                   "Pipe operators are not supported on this statement");
      }
    }  return absl::OkStatus();
}
