absl::Status Parser::action1100([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTQuery*>();
{
      ASTQuery* query = std::get<ASTQuery*>(rhs[0].value);
      if (query->parenthesized()) {
        // When we have a pipe operator following a parenthesized query, rather
        // than just adding it on, we created a nested query expression, so
        // we get a better representation of how the pipes bind.
        // We set is_nested for the Unparser, and unset parenthesized to avoid
        // printing double-parentheses.
        query->set_is_nested(true);
        query->set_parenthesized(false);
        std::get<ASTQuery*>(lhs.value) = MakeNode<ASTQuery>(lhs.sym.location, query, std::get<ASTPipeOperator*>(rhs[1].value));
      } else {
        std::get<ASTQuery*>(lhs.value) = ExtendNodeRight(query, std::get<ASTPipeOperator*>(rhs[1].value));
      }
    }  return absl::OkStatus();
}
