absl::Status Parser::action1294([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTNode*>();
{
      // "VALUE" is a valid identifier, so it can be a valid path expression.
      // But AS VALUE has a special meaning as a SELECT statement mode. We
      // handle it here, but only when VALUE is used without backquotes. With
      // backquotes the `VALUE` is treated like a regular path expression.
      bool is_value = false;
      if (std::get<ASTPathExpression*>(rhs[1].value)->num_children() == 1) {
        GOOGLESQL_RET_CHECK(std::get<ASTPathExpression*>(rhs[1].value)->child(0)->Is<ASTIdentifier>());
        auto* identifier = std::get<ASTPathExpression*>(rhs[1].value)->child(0)->GetAsOrDie<ASTIdentifier>();
        if (!identifier->is_quoted() &&
            googlesql_base::CaseEqual(identifier->GetAsStringView(), "VALUE")) {
          auto* select_as = MakeNode<ASTSelectAs>(lhs.sym.location);
          select_as->set_as_mode(ASTSelectAs::VALUE);
          std::get<ASTNode*>(lhs.value) = select_as;
          is_value = true;
        }
      }
      if (!is_value) {
        auto* select_as = MakeNode<ASTSelectAs>(lhs.sym.location, std::get<ASTPathExpression*>(rhs[1].value));
        select_as->set_as_mode(ASTSelectAs::TYPE_NAME);
        std::get<ASTNode*>(lhs.value) = select_as;
      }
    }  return absl::OkStatus();
}
