absl::Status Parser::action1681([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTGraphPathPattern*>();
{
      // if std::get<ASTGraphPathBase*>(rhs[0].value) is a subpath, return itself; Otherwise it's an element scan,
      // wrap it with a path. Not wrapping subpath because it's only necessary
      // to wrap it in the branch below.
      std::get<ASTGraphPathPattern*>(lhs.value) = std::get<ASTGraphPathBase*>(rhs[0].value)->Is<ASTGraphPathPattern>()
                ? std::get<ASTGraphPathBase*>(rhs[0].value)->GetAsOrDie<ASTGraphPathPattern>()
                : MakeNode<ASTGraphPathPattern>(lhs.sym.location, std::get<ASTGraphPathBase*>(rhs[0].value));
    }  return absl::OkStatus();
}
absl::Status Parser::action1682([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTGraphPathPattern*>();
{
      // Wrap std::get<ASTGraphPathPattern*>(rhs[0].value) if it's a subpath (a base case from the above branch), in order
      // to extend the wrapper to std::get<ASTGraphPathBase*>(rhs[2].value)'s location. No need to wrap if its already
      // a path concatenation.
      auto* path =
          !std::get<ASTGraphPathPattern*>(rhs[0].value)->parenthesized() ? std::get<ASTGraphPathPattern*>(rhs[0].value) : MakeNode<ASTGraphPathPattern>(lhs.sym.location, std::get<ASTGraphPathPattern*>(rhs[0].value));
      auto* next_element = std::get<ASTGraphPathBase*>(rhs[2].value);
      if (std::optional<ASTNode*>(std::get<ASTNode*>(rhs[1].value)).has_value()) {
        ASTGraphPathBase* last_element =
            path->mutable_child(path->num_children() - 1)
                ->GetAsOrDie<ASTGraphPathBase>();
        // Hints in between two edges are ambiguous.
        if (last_element->Is<ASTGraphEdgePattern>() &&
            next_element->Is<ASTGraphEdgePattern>()) {
          return MakeSyntaxError(std::optional<decltype(lhs.sym.location)>(rhs[1].sym.location),
                              absl::StrCat(
                                "Hint cannot be used in between two ",
                                last_element->GetNodeKindString(), "s"));
        }
        // If either element is an edge, attach the hint to the edge.
        if (next_element->Is<ASTGraphEdgePattern>()) {
          auto* lhs_hint = MakeNode<ASTGraphLhsHint>(*std::optional<decltype(lhs.sym.location)>(rhs[1].sym.location), std::optional<ASTNode*>(std::get<ASTNode*>(rhs[1].value)));
          ExtendNodeLeft(next_element, lhs_hint);
        } else if (last_element->Is<ASTGraphEdgePattern>()) {
          auto* rhs_hint = MakeNode<ASTGraphRhsHint>(*std::optional<decltype(lhs.sym.location)>(rhs[1].sym.location), std::optional<ASTNode*>(std::get<ASTNode*>(rhs[1].value)));
          // TODO: b/376552156 - Add rhs_hint to back and remove this location reset.
          auto start = last_element->start_location();
          ExtendNodeLeft(last_element, start, rhs_hint);
          last_element->set_end_location(rhs_hint->end_location());

          // Each path pattern can have only up to 1 LHS and RHS hint each.
          // If both exist, swap them here so that they're in the order expected
          // by the tree parser.
          int lhs_idx = last_element->find_child_index(
              AST_GRAPH_LHS_HINT);
          int rhs_idx = last_element->find_child_index(
              AST_GRAPH_RHS_HINT);

          if (lhs_idx >=0 && last_element->SwapChildren(
              lhs_idx, rhs_idx) != true) {
            // Failed to swap LHS and RHS hint even though both exist.
            return MakeSyntaxError(
                *std::optional<decltype(lhs.sym.location)>(rhs[1].sym.location), "Unable to parse hints in the right order");
          }
        } else {
          // Currently ASTGraphNodePattern does not support attaching hints. So
          // wrap node patterns in path patterns and attach hints to the path
          // patterns.
          if (next_element->Is<ASTGraphNodePattern>()) {
            next_element = MakeNode<ASTGraphPathPattern>(lhs.sym.location, next_element);
          }
          ExtendNodeLeft(next_element, std::optional<ASTNode*>(std::get<ASTNode*>(rhs[1].value)));
        }
      }
      std::get<ASTGraphPathPattern*>(lhs.value) = ExtendNodeRight(path, lhs.sym.location.end(), next_element);
    }  return absl::OkStatus();
}
