absl::Status Parser::action2391([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTStringLiteralComponent*>();
{
      std::string str;
      std::string error_string;
      int error_offset;
      const absl::Status parse_status = ParseStringLiteral(
          std::get<absl::string_view>(rhs[0].value), &str, &error_string, &error_offset);
      if (!parse_status.ok()) {
        auto location = rhs[0].sym.location;
        location.mutable_start().IncrementByteOffset(error_offset);
        if (!error_string.empty()) {
          return MakeSyntaxError(location,
                                absl::StrCat("Syntax error: ", error_string));
        }
        ABSL_DLOG(FATAL) << "ParseStringLiteral did not return an error string";
        return MakeSyntaxError(location,
                              absl::StrCat("Syntax error: ",
                                          parse_status.message()));
      }

      auto* literal = MakeNode<ASTStringLiteralComponent>(rhs[0].sym.location);
      literal->set_string_value(std::move(str));
      // TODO: Migrate to absl::string_view or avoid having to
      // set this at all if the client isn't interested.
      literal->set_image(std::string(std::get<absl::string_view>(rhs[0].value)));
      std::get<ASTStringLiteralComponent*>(lhs.value) = literal;
    }  return absl::OkStatus();
}
