absl::Status Parser::action2408([[maybe_unused]] stackEntry& lhs,
                        [[maybe_unused]] const stackEntry* rhs) {

  lhs.value.emplace<ASTIdentifier*>();
{
      const absl::string_view identifier_text(std::get<absl::string_view>(rhs[0].value));
      // The tokenizer rule already validates that the identifier is valid,
      // except for backquoted identifiers.
      if (identifier_text[0] == '`') {
        std::string str;
        std::string error_string;
        int error_offset;
        const absl::Status parse_status =
            ParseGeneralizedIdentifier(
                identifier_text, &str, &error_string, &error_offset);
        if (!parse_status.ok()) {
          auto location = rhs[0].sym.location;
          location.mutable_start().IncrementByteOffset(error_offset);
          if (!error_string.empty()) {
            return MakeSyntaxError(location,
                                   absl::StrCat("Syntax error: ",
                                                error_string));
          }
          ABSL_DLOG(FATAL) << "ParseIdentifier did not return an error string";
          return MakeSyntaxError(location,
                                 absl::StrCat("Syntax error: ",
                                              parse_status.message()));
        }
        std::get<ASTIdentifier*>(lhs.value) = node_factory.MakeIdentifier(rhs[0].sym.location, str, /*is_quoted=*/true);
      } else {
        std::get<ASTIdentifier*>(lhs.value) = node_factory.MakeIdentifier(rhs[0].sym.location, identifier_text, /*is_quoted=*/false);
      }
    }  return absl::OkStatus();
}
